evidence.command:
for d in human event schedule external; do python3 examples/ask/run.py --door $d --again --ledger examples/ask/out/q5-$d.jsonl --json | python3 -c "
import json,sys; r=json.load(sys.stdin)
print('$d', r[0]['claim'], '->', r[1]['claim'], 'entries', r[1]['entries_recorded'], 'same body', r[0]['receipt']==r[1]['receipt'], end='  |  ')"; done; echo

RACE_DELAY_S=0.02 python3 harness/idempotency/conformance.py --adapter dryrun --report harness/idempotency/out/q2.json >/dev/null 2>&1; python3 -c "
import json; r=json.load(open('harness/idempotency/out/q2.json'))
print('the default fold binding, 20 concurrent claims of one key:', r['executions'], 'executions, cases passed', r['cases_passed'], 'of', r['cases_run'])"

for d in human event schedule external; do python3 examples/ask/run.py --door $d --again --ledger examples/ask/out/q5-$d.jsonl --json | python3 -c "
import json,sys; r=json.load(sys.stdin)
print('$d', r[0]['claim'], '->', r[1]['claim'], 'entries', r[1]['entries_recorded'], 'same body', r[0]['receipt']==r[1]['receipt'], end='  |  ')"; done; echo

python3 examples/ask/run.py --door schedule --again-received-at 2026-09-04T06:00:00Z --ledger examples/ask/out/q5s.jsonl --json | python3 -c "
import json,sys; r=json.load(sys.stdin)
print('catch-up of the same occurrence at a later wall clock:', 'same key' if r[0]['idempotency_key']==r[1]['idempotency_key'] else 'DIFFERENT key', r[1]['claim'], 'entries', r[1]['entries_recorded'])"

python3 examples/ask/run.py --all-doors --json --ledger examples/ask/out/q5.jsonl 2>&1 | python3 -c "
import json,sys; r=json.load(sys.stdin)
print('one job digest', len({x['job_digest'] for x in r}), '| keys', len({x['idempotency_key'] for x in r}), '| claims', [x['claim'] for x in r], '| entries recorded', r[-1]['entries_recorded'])"

RACE_DELAY_S=0.02 python3 harness/idempotency/conformance.py --adapter dryrun --report harness/idempotency/out/q2.json >/dev/null 2>&1; python3 -c "
import json; r=json.load(open('harness/idempotency/out/q2.json'))
print('the default fold binding, 20 concurrent claims of one key:', r['executions'], 'executions, cases passed', r['cases_passed'], 'of', r['cases_run'])"
